INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(1, 1, 'Goku', '60.000.000', '90 Septillion', 'Saiyan', 'Male', 'Z Fighter', 'El protagonista de la serie, conocido por su gran poder y personalidad amigable. Originalmente enviado a la Tierra como un infante volador con la misión de conquistarla. Sin embargo, el caer por un barranco le proporcionó un brutal golpe que si bien casi lo mata, este alteró su memoria y anuló todos los instintos violentos de su especie, lo que lo hizo crecer con un corazón puro y bondadoso, pero conservando todos los poderes de su raza. No obstante, en la nueva continuidad de Dragon Ball se establece que él fue enviado por sus padres a la Tierra con el objetivo de sobrevivir a toda costa a la destrucción de su planeta por parte de Freeza. Más tarde, Kakarot, ahora conocido como Son Goku, se convertiría en el príncipe consorte del monte Fry-pan y líder de los Guerreros Z, así como el mayor defensor de la Tierra y del Universo 7, logrando mantenerlos a salvo de la destrucción en innumerables ocasiones, a pesar de no considerarse a sí mismo como un héroe o salvador.', 'https://dragonball-api.com/characters/goku_normal.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(2, 2, 'Vegeta', '54.000.000', '19.84 Septillion', 'Saiyan', 'Male', 'Z Fighter', 'Príncipe de los Saiyans, inicialmente un villano, pero luego se une a los Z Fighters. A pesar de que a inicios de Dragon Ball Z, Vegeta cumple un papel antagónico, poco después decide rebelarse ante el Imperio de Freeza, volviéndose un aliado clave para los Guerreros Z. Con el paso del tiempo llegaría a cambiar su manera de ser, optando por permanecer y vivir en la Tierra para luchar a su lado contra las inminentes adversidades que superar. Junto con Piccolo, él es de los antiguos enemigos de Goku que ha evolucionando al pasar de ser un villano y antihéroe, a finalmente un héroe a lo largo del transcurso de la historia, convirtiéndose así en el deuteragonista de la serie.', 'https://dragonball-api.com/characters/vegeta_normal.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(3, 3, 'Piccolo', '2.000.000', '500.000.000', 'Namekian', 'Male', 'Z Fighter', 'Es un namekiano que surgió tras ser creado en los últimos momentos de vida de su padre, siendo su actual reencarnación. Aunque en un principio fue el archienemigo de Son Goku, con el paso del tiempo fue haciéndose menos malvado hasta finalmente convertirse en un ser bondadoso y miembro de los Guerreros Z. A través del tiempo, también comenzó a tomarle cariño a su discípulo Son Gohan, a quien veía como una especie de \"vástago\" y formando un lazo de amistad con este.', 'https://dragonball-api.com/characters/picolo_normal.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(4, 4, 'Bulma', '0', '0', 'Human', 'Female', 'Z Fighter', 'Bulma es la protagonista femenina de la serie manga Dragon Ball y sus adaptaciones al anime Dragon Ball, Dragon Ball Z, Dragon Ball Super y Dragon Ball GT. Es hija del Dr. Brief y su esposa Panchy, hermana menor de Tights y una gran amiga de Son Goku con quien inicia la búsqueda de las Esferas del Dragón. En Dragon Ball Z tuvo a Trunks, primogénito de quien sería su esposo Vegeta, a su hija Bra[3] y su hijo adulto del tiempo alterno Trunks del Futuro Alternativo.', 'https://dragonball-api.com/characters/bulma.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(5, 5, 'Freezer', '530.000', '52.71 Septillion', 'Frieza Race', 'Male', 'Army of Frieza', 'Freezer es el tirano espacial y el principal antagonista de la saga de Freezer.', 'https://dragonball-api.com/characters/Freezer.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(6, 6, 'Zarbon', '20.000', '30.000', 'Frieza Race', 'Male', 'Army of Frieza', 'Zarbon es uno de los secuaces de Freezer y un luchador poderoso.', 'https://dragonball-api.com/characters/zarbon.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(7, 7, 'Dodoria', '18.000', '20.000', 'Frieza Race', 'Male', 'Army of Frieza', 'Dodoria es otro secuaz de Freezer conocido por su brutalidad.', 'https://dragonball-api.com/characters/dodoria.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(8, 8, 'Ginyu', '9.000', '25.000', 'Frieza Race', 'Male', 'Army of Frieza', 'Ginyu es el líder del la élite de mercenarios de mayor prestigio del Ejército de Freeza, la cual lleva el nombre de Fuerzas Especiales Ginew en su honor[9].', 'https://dragonball-api.com/characters/ginyu.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(9, 9, 'Celula', '250.000.000', '5 Billion', 'Android', 'Male', 'Freelancer', 'Cell conocido como Célula en España, es un bioandroide creado por la computadora del Dr. Gero, quien vino del futuro de la línea 3 con la intención de vengarse de Goku por haber acabado con el Ejército del Listón Rojo, y con ello el sueño de todo villano: dominar el mundo. Es el antagonista principal del Arco de los Androides y Cell.', 'https://dragonball-api.com/characters/celula.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(10, 10, 'Gohan', '45.000.000', '40 septillion', 'Saiyan', 'Male', 'Z Fighter', 'Son Gohanda en su tiempo en España, o simplemente Gohan en Hispanoamérica, es uno de los personajes principales de los arcos argumentales de Dragon Ball Z, Dragon Ball Super y Dragon Ball GT. Es un mestizo entre saiyano y humano terrícola. Es el primer hijo de Son Goku y Chi-Chi, hermano mayor de Son Goten, esposo de Videl y padre de Pan.', 'https://dragonball-api.com/characters/gohan.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(11, 11, 'Krillin', '1.000.000', '1 Billion', 'Human', 'Male', 'Z Fighter', 'Amigo cercano de Goku y guerrero valiente, es un personaje del manga y anime de Dragon Ball. Es uno de los principales discípulos de Kame-Sen\'nin, Guerrero Z, y el mejor amigo de Son Goku. Es junto a Bulma uno de los personajes de apoyo principales de Dragon Ball, Dragon Ball Z y Dragon Ball Super. Aparece en Dragon Ball GT como personaje secundario. En el Arco de Majin Boo, se retira de las artes marciales, optando por formar una familia, como el esposo de la Androide Número 18 y el padre de Marron.', 'https://dragonball-api.com/characters/Krilin_Universo7.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(12, 12, 'Tenshinhan', '2.400.000', '80.000.000', 'Human', 'Male', 'Z Fighter', 'Maestro de las artes marciales y miembro de los Z Fighters.  Es un personaje que aparece en el manga y en el anime de Dragon Ball, Dragon Ball Z, Dragon Ball GT y posteriormente en Dragon Ball Super.', 'https://dragonball-api.com/characters/Tenshinhan_Universo7.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(13, 13, 'Yamcha', '1.980.000', '4.000.000', 'Human', 'Male', 'Z Fighter', 'Luchador que solía ser un bandido del desierto.', 'https://dragonball-api.com/characters/Final_Yamcha.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(14, 14, 'Chi-Chi', '0', '0', 'Human', 'Female', 'Z Fighter', 'Esposa de Goku y madre de Gohan. Es la princesa del Monte Fry-pan siendo la hija de la fallecida reina de esta montaña y el Rey Gyuma, ella terminaría conociendo a Son Goku cuando era tan solo una niña para años más tarde durante su adolescencia ser su esposa y convertirse en la estricta pero amorosa madre de Gohan y Goten.', 'https://dragonball-api.com/characters/ChiChi_DBS.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(15, 15, 'Gotenks', '65.600.000', '34.8 Billion', 'Saiyan', 'Male', 'Z Fighter', ' Gotenks también conocido inicialmente como Gotrunk en el doblaje al español de España, es el resultado de la Danza de la Fusión llevada a cabo correctamente por Goten y Trunks.', 'https://dragonball-api.com/characters/Gotenks_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(16, 16, 'Trunks', '50.000.000', '37.4 septllion', 'Saiyan', 'Male', 'Z Fighter', 'Hijo de Vegeta y Bulma. Es un mestizo entre humano terrícola y Saiyano nacido en la Tierra, e hijo de Bulma y Vegeta, el cual es introducido en el Arco de los Androides y Cell. Más tarde en su vida como joven, se termina convirtiendo en un luchador de artes marciales, el mejor amigo de Son Goten y en el hermano mayor de su hermana Bra.', 'https://dragonball-api.com/characters/Trunks_Buu_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(17, 17, 'Master Roshi', '500.000', '350.000.000', 'Human', 'Male', 'Z Fighter', 'Maestro de artes marciales y mentor de Goku. Conocido bajo el nombre de Muten Rosh, fue en su momento el terrícola más fuerte de la Tierra, y mucha gente lo recuerda como el \"Dios de las Artes Marciales\", pero antes de poder ostentar dicho título tuvo que trabajar y estudiar las artes marciales con su maestro Mutaito y su eterno rival Tsuru-Sen\'nin.', 'https://dragonball-api.com/characters/roshi.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(18, 18, 'Bardock', '450.000', '180.000.000', 'Saiyan', 'Male', 'Z Fighter', 'Es un saiyano de clase baja proveniente del Planeta Vegeta del Universo 7. Pertenece al Ejército Saiyano, que está bajo el liderazgo del Rey Vegeta, y es jefe de su escuadrón durante la anexión del planeta por parte de las fuerzas coloniales del Imperio de Freeza. Él es el esposo de Gine y padre biológico de Kakarotto y Raditz.', 'https://dragonball-api.com/characters/Bardock_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(19, 19, 'Launch', '0', '0', 'Human', 'Female', 'Z Fighter', 'Personaje que sufre cambios de personalidad al estornudar. Es uno de los personajes principales del manga Dragon Ball y su anime homónimo; Lunch es una chica que sufre de un trastorno de personalidad doble que a raíz de sus reacciones alérgicas provoca que ella cambie entre dos personalidades diferentes, ninguna de las personalidades recuerda lo que la otra hizo o dijo.', 'https://dragonball-api.com/characters/Lunch_traje_de_sirvienta_en_el_manga.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(20, 20, 'Mr. Satan', '450', '5.000', 'Human', 'Male', 'Other', 'Luchador humano famoso por llevarse el mérito de las victorias de los Guerreros Z.', 'https://dragonball-api.com/characters/Mr_Satan_DBSuper.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(21, 21, 'Dende', '3.200', '3.200', 'Namekian', 'Male', 'Z Fighter', 'Sucesor de Piccolo como el nuevo Namekian protector de la Tierra. Es un pequeño namekiano, que vivía en el poblado de Moori, junto a su hermano Scargo y otros tantos de su especie. Es el hijo 108 del Gran Patriarca y posteriormente Dios de la Tierra, sustituyendo a Dios.', 'https://dragonball-api.com/characters/Dende_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(22, 22, 'Android 17', '320.000.000', '40 Quintillion', 'Android', 'Male', 'Villain', 'Antes de ser secuestrado, es el hermano mellizo de la Androide Número 18, quien al igual que ella antes de ser Androide era un humano normal hasta que fueron secuestrados por el Dr. Gero, y es por eso que lo odian. Tras su cambio de humano a Androide, le insertaron un chip con el objetivo de destruir a Son Goku, quien en su juventud extermino al Ejército del Listón Rojo. Al considerarse defectuoso porque no quería ser \'esclavo de nadie\', el Dr. Gero les había colocado a ambos hermanos, un dispositivo de apagado para detenerlos en cualquier momento de desobediencia, pero cuando el científico los despierta, el rencor y rebeldía de 17 eran tal que se encargó de destruir el control que lo volvería a encerrar y acto seguido mató sin piedad a su propio creador. Su situación se le iría en contra, ya que Cell tenía como misión absorber a 17 y 18 para completar su desarrollo y convertirse en Cell Perfecto.', 'https://dragonball-api.com/characters/17_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(23, 23, 'Android 16', '440.000.000', '440.000.000', 'Android', 'Male', 'Villain', 'Android 16 es un androide gigante conocido por su amor a la naturaleza y la vida.', 'https://dragonball-api.com/characters/Androide_16.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(24, 24, 'Android 19', '122.000.000', '160,000,000', 'Android', 'Male', 'Villain', 'Android 19 es uno de los androides creados por el Dr. Gero.', 'https://dragonball-api.com/characters/Android19.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(25, 25, 'Android 20 (Dr. Gero)', '128.000.000', '158.100.000', 'Android', 'Male', 'Villain', 'Dr. Gero es el científico loco que creó a los androides 17, 18 y 19.', 'https://dragonball-api.com/characters/Dr._Gero nadroide 20.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(26, 26, 'Android 13', '195.000.000', '562.500.000', 'Android', 'Male', 'Villain', 'Android 13 es un androide peligroso que aparece en la película \"El Regreso de Cooler\".', 'https://dragonball-api.com/characters/Androide13normal.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(27, 27, 'Android 14', '192.500.000', '192.500.000', 'Android', 'Male', 'Villain', 'Android 14 es otro androide que aparece en la misma película que Android 13.', 'https://dragonball-api.com/characters/14Dokkan.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(28, 28, 'Android 15', '175.000.000', '175.000.000', 'Android', 'Male', 'Villain', 'Android 15 es otro androide que aparece en la misma película que Android 13.', 'https://dragonball-api.com/characters/15Dokkan.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(29, 29, 'Nail', '42.000 ', '42.000', 'Namekian', 'Male', 'Z Fighter', 'Es un Namekiano (habitante del planeta Namek), que se caracteriza por formar parte de los escasos miembros de la \"estirpe guerrera\", y ser el más poderoso entre ellos junto a Piccolo.', 'https://dragonball-api.com/characters/Nail_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(30, 30, 'Raditz', '1.500 ', '1.500 ', 'Saiyan', 'Male', 'Army of Frieza', 'Es el hijo de Bardock y Gine, y hermano mayor de Son Goku. Él es uno de los pocos saiyanos que sobrevivieron a la destrucción del Planeta Vegeta, y formaba parte del equipo de Vegeta. Es el primer antagonista de Dragon Ball Z.', 'https://dragonball-api.com/characters/Raditz_artwork_Dokkan.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(31, 31, 'Babidi', '0', '0', 'Majin', 'Male', 'Villain', 'Conocido también como Bóbidi o Bábidi, es un poderoso hechicero madoshi, \"hijo\" del gran mago Bibbidi, fundador de la familia Majin. La \"M\" que llevan ambos en el cinturón de sus atuendos al igual que la frente de aquellos que han sido poseídos para formar parte de la familia Majin.', 'https://dragonball-api.com/characters/Babidi_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(32, 32, 'Majin Buu', '8 Billion', '100 Trillion', 'Majin', 'Male', 'Villain', 'También conocido como Boo original, es la forma original y pura de Majin-Boo, y la última forma de Boo que aparece en Dragon Ball Z.', 'https://dragonball-api.com/characters/BuuGordo_Universo7.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(33, 33, 'Bills', '102 Billion', '100 septillion', 'God', 'Male', 'Other', 'Dios de la Destrucción Beerus, conocido también como Beers, o Bills en Hispanoamérica e inicialmente en España[1], es un personaje que fue introducido en la película Dragon Ball Z: La batalla de los dioses, donde es el antagonista principal de la película, y que aparece en el manga y anime de Dragon Ball Super como un personaje principal. Ocupa el puesto de Dios de la Destrucción de todo el Universo 7 siendo el lugar donde se desarrolla la historia de Dragon Ball.', 'https://dragonball-api.com/characters/Beerus_DBS_Broly_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(34, 34, 'Whis', '15 septillion', '110 septillion', 'Angel', 'Male', 'Assistant of Beerus', 'Whis es uno de los hijos del Gran Sacerdote, hermano menor de Vados, Korn y Kus. Es el ángel guía encargado de asistir y servir como maestro al Dios de la Destrucción del Universo 7, Beerus.', 'https://dragonball-api.com/characters/Whis_DBS_Broly_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(35, 35, 'Zeno', '500 Septillion', '500 Septillion', 'Unknown', 'Male', 'Other', 'Zeno es el ser supremo del multiverso y tiene un poder abrumador .El Rey de Todo, también conocido como Zen Oo (Zeno Sama en España y Zen Oo Sama en Hispanoamerica) y apodado por Son Goku como Todito (全ぜんちゃん, Zen-chan), es el gobernante y dios absoluto de todos los universos y el máximo soberano de todo lo existente en Dragon Ball.', 'https://dragonball-api.com/characters/Zeno_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(36, 37, 'Kibito-Shin', '3.2 Billion', '3.2 Billion', 'God', 'Male', 'Other', 'es la fusión entre Shin y Kibito. Ellos fueron unidos permanentemente mediante el uso de los míticos pendientes Pothala. Está actualmente separado gracias a un deseo concedido por las Esferas del Dragón namekianas.', 'https://dragonball-api.com/characters/Kibito_shin_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(37, 38, 'Jiren', '121 Quintillion', '12.1 Septillion', 'Jiren Race', 'Male', 'Pride Troopers', 'Jiren es un poderoso luchador del Universo 11 y uno de los oponentes más formidables en el torneo.', 'https://dragonball-api.com/characters/Jiren.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(38, 39, 'Toppo', '99 Quadrillion', '7.5 Sextillion', 'God', 'Male', 'Pride Troopers', 'Toppo es el líder de las Tropas del Orgullo, guerreros de la justicia del Universo 11 que actúan como protectores de la paz y superhéroes del bien. Él ha sido entrenado por el ángel guía Marcarita, convirtiéndose así en un candidato como futuro Dios de la Destrucción en su universo.', 'https://dragonball-api.com/characters/Toppo.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(39, 40, 'Dyspo', '50 Trillion', '150 Quintillion', 'God', 'Male', 'Pride Troopers', 'Dyspo es uno de los miembros del Equipo Universo 11 como uno de los soldados más poderosos de las Tropas del Orgullo junto con Jiren y su líder Toppo.', 'https://dragonball-api.com/characters/Dispo_render.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(40, 42, 'Marcarita ', '10 septillion', '99.5 septillion', 'Angel', 'Female', 'Assistant of Vermoud', 'Marcarita es el ángel guía del Universo 11, sirviente y maestra de artes marciales del Dios de la Destrucción Vermoud. Es un personaje de la Arco de la Supervivencia Universal de Dragon Ball Super.', 'https://dragonball-api.com/characters/Marcarita.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(41, 43, 'Vermoudh', '9.9 Septillion', '100 septillion', 'God', 'Male', 'Pride Troopers', 'Es el individuo que actualmente ostenta el cargo de Dios de la Destrucción en el Universo 11, puesto que obtuvo tras abandonar su membresía como Soldado del Orgullo dentro de las Tropas del Orgullo.', 'https://dragonball-api.com/characters/Vermoud.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(42, 44, 'Grand Priest ', '969 Googolplex', '969 Googolplex', 'Angel', 'Male', 'Other', 'El Gran Sacerdote es el supervisor del torneo y uno de los seres más poderosos. Gran Ministro de los Omni-Reyes , es un ángel que actúa como asesor cercano y figura guía de Zenón y del Futuro Zenón . De vez en cuando hace cumplir los Decretos Divinos de los Zenos y da la bienvenida a los invitados a su palacio . El Gran Ministro es también padre de trece Ángeles, de los cuales doce sirven a los Dioses de la Destrucción . Por su posición y poder, es quizás el segundo ser más fuerte del Multiverso .', 'https://dragonball-api.com/characters/Grand priest.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(43, 63, 'Kaio del norte (Kaito)', '6.000', '6.000', 'Nucleico benigno', 'Male', 'Other', 'Se trata del dios encargado de administrar las Galaxias del Norte, el cuadrante boreal del Universo 7 y supervisar a los dioses de los planetas de dicho sector (como es el caso de Kami en la Tierra)', 'https://dragonball-api.com/characters/Kaio_del_Norte.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(44, 64, 'Android 18', '280,000,000', '300,000,000', 'Android', 'Female', 'Z Fighter', 'Es la hermana melliza del Androide Número 17 y una \"androide\" creada a partir de una base humana por el Dr. Gero con el único fin de destruir a Goku.', 'https://dragonball-api.com/characters/Androide_18_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(45, 65, 'Gogeta', '250 Billion', '15 septillion', 'Saiyan', 'Male', 'Z Fighter', 'Gogeta es la fusión resultante de Son Goku y Vegeta, cuando realizan la Danza de la Fusión correctamente para enfrentarse a Broly. Su voz es una voz dual que contiene las voces de Goku y Vegeta. Junto con el poder todopoderoso de los dos, con la astucia y perspicacia de Vegeta, y la habilidad pródiga de las artes marciales de Goku, es uno de los guerreros más temibles para desafiar a una pelea.', 'https://dragonball-api.com/transformaciones/gogeta.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(46, 66, 'Vegetto', '180 Billion', '10.8 Septillion', 'Saiyan', 'Male', 'Z Fighter', 'Vegetto es el personaje más fuerte dentro del manga original y uno de los personajes más poderosos de toda la serie en general. Su poder es el resultado del máximo poder combinado de Goku y Vegeta, multiplicado varias veces su fuerza, siendo una de las fusiones más poderosas dentro de la franquicia.', 'https://dragonball-api.com/transformaciones/Vegetto.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(47, 67, 'Janemba', '15 Billion', '75 Billion', 'Evil', 'Male', 'Other', 'Janemba es un demonio de pura maldad y gran poder maligno. Creado a partir de las acciones de un adolescente ogro llamado Psyche Oni, quien era el responsable de vigilar la máquina purificadora de almas, la cual explota como consecuencia de la falta de cuidado del ogro, las almas malignas terminan por usar como huésped su cuerpo, creando así a este demonio.', 'https://dragonball-api.com/transformaciones/Janemba_artwork_SDBH.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(48, 68, 'Broly', '7 quadrillion', '11.2 Septillion', 'Saiyan', 'Male', 'Other', 'Broly es un Saiyajin que posee un poder gigantesco e incontrolable, el cual se manifiesta en toda su magnitud cuando se convierte en el Super Saiyajin Legendario. Incluso cuando apenas era un bebé su nivel de poder alcanzaba cifras inmensas que provocaban asombro y preocupación entre los de su raza', 'https://dragonball-api.com/transformaciones/Broly_DBS_Base.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(49, 69, 'Kaio del Sur', 'unknown', 'unknown', 'Nucleico benigno', 'Male', 'Other', 'El Kaio del Sur es la única referencia que tenemos de los otros dioses Kaiō en el manga, más allá del Kaiō Sama Norte ya que es el único Kaiō, junto con el Kaiō del Norte, en aparecer en el manga, y uno de los cuatro que aparecen en el anime, junto al Gran Kaio.', 'https://dragonball-api.com/characters/Kaio_del_sur_cuerpo_completo.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(50, 70, 'Kaio del este', 'unknown', 'unknown', 'Nucleico benigno', 'Female', 'Other', 'La Kaiō del Este es una Kaio que solo aparece en el anime. Le gustan los retos y de entrenar duramente a sus discípulos, que destacan por ser guerreros muy veloces, siendo el ejemplo más claro Chapuchai.', 'https://dragonball-api.com/characters/kaio del este.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(51, 71, 'Kaio del Oeste', 'unknown', 'unknown', 'Nucleico benigno', 'Male', 'Other', 'El Kaiō del Oeste es el rival del Kaio del Norte. Y como dice su nombre, el controla la galaxia del Oeste.', 'https://dragonball-api.com/characters/Kaio del oeste.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(52, 72, 'Gran Kaio', 'unknown', 'unknown', 'Nucleico benigno', 'Male', 'Other', 'Gran Kaio es el Kaio de mayor importancia del Otro Mundo y es el Dios que se encarga de administrar a los demás Kaiō para que se ocupen de cuyos sectores de la Galaxia. Su apariencia es la de un anciano con una barba larga y muy canosa, remarcada por unas gafas oscuras que nunca se quita en la serie. Cuenta con su propio planeta, el Planeta del Gran Kaio, en el cual la gravedad es 10 veces mayor a la del planeta Tierra.', 'https://dragonball-api.com/characters/Gran_kaio_sama12.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(53, 73, 'Kaio-shin del Este', 'unknown', 'unknown', 'Nucleico', 'Male', 'Other', 'Es uno de los Kaio-shin, los dioses de la creación que se encargan de crear vida en todo el Universo 7 y protegerlo de amenazas supremas.\nAnteriormente solía hacerse cargo de proteger la zona este del universo, ya que después de la muerte de los otros Kaio-shin a manos de Majin-Boo, se convirtió en el Kaio-shin principal del Universo 7.', 'https://dragonball-api.com/characters/Kaio-shin_del_este_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(54, 74, 'Kaio-shin del Norte', 'unknown', 'unknown', 'Nucleico', 'Male', 'Other', 'El Kaiō-shin del Norte es otro de los Kaiō-shin que vivió junto a el resto de los Kaio-shin y Dai Kaio-shin hace 5 millones de años, y que luchó contra Majin Boo.', 'https://dragonball-api.com/characters/Kaio-shin del norte.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(55, 75, 'Kaio-shin del Sur', 'unknown', 'unknown', 'Nucleico', 'Male', 'Other', 'El Kaio-shin del Sur fue el gobernante del cuadrante sur del universo y era el más poderoso entre los Kaio-shin.', 'https://dragonball-api.com/characters/Kaio-shin_del_Sur_Dokkan.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(56, 76, 'Kaio-shin del Oeste', 'unknown', 'unknown', 'Nucleico benigno', 'Female', 'Other', 'La Kaiō-shin del Oeste es una Kaio-shin, que vivió junto a sus compañeros, fue la primera en morir en la terrible batalla librada contra Majin Boo hace 5 millones de años.', 'https://dragonball-api.com/characters/Kaio-shin_del_Oeste_Dokkan.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(57, 77, 'Gran Kaio-shin', 'unknown', 'unknown', 'Nucleico benigno', 'Male', 'Other', 'El Gran Kaio-shin, conocido también como Sagrado Kaiosama en Hispanoamérica, era el Kaio-shin principal del Universo 7 y supervisor de los otros Kaio-shin del mismo universo.\nTras ser absorbido por Majin Boo, el Gran Kaio-shin del Universo 7 se convirtió en la faceta más dominante en Boo Gordo, aún viviendo actualmente dentro de su cuerpo a través de su espíritu.', 'https://dragonball-api.com/characters/Gran_Kaio-shin_Artwork.webp', );
INSERT INTO `personajes` (`id`, `id_api`, `name`, `ki`, `max_ki`, `race`, `gender`, `affiliation`, `description`, `image_url`, `image_blob`) VALUES
(58, 78, 'Kibito', 'unknown', 'unknown', 'Nucleico', 'Male', 'Other', 'Kibito es el ayudante y guardaespaldas del Kaio-shin del Este. Es un experto combatiente y con ciertos poderes curativos y mágicos como corresponde a su función. Su técnica más conocida es el Kai-Kai.', 'https://dragonball-api.com/characters/Kibito_Artwork.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(1, 1, 'Namek', 1, 'Planeta natal de los Namekianos. Escenario de importantes batallas y la obtención de las Dragon Balls de Namek.', 'https://dragonball-api.com/planetas/Namek_U7.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(2, 2, 'Tierra', 0, 'La Tierra también llamado Mundo del Dragón (Dragon World), es el planeta principal donde se desarrolla la serie de Dragon Ball. Se encuentra en el Sistema Solar de la Vía Láctea de las Galaxias del Norte del Universo 7, lugar que supervisa el Kaio del Norte, y tiene su equivalente en el Universo 6. El hogar de los terrícolas y los Guerreros Z. Ha sido atacado en varias ocasiones por enemigos poderosos.', 'https://dragonball-api.com/planetas/Tierra_Dragon_Ball_Z.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(3, 3, 'Vegeta', 1, 'El planeta Vegeta, conocido como planeta Plant antes del fin de la Guerra Saiyan-tsufruiana en el año 730, es un planeta rocoso ficticio de la serie de manga y anime Dragon Ball y localizado en la Vía Láctea de las Galaxias del Norte del Universo 7 hasta su destrucción a manos de Freezer en los años 737-739. Planeta natal de los Saiyans, destruido por Freezer. Anteriormente conocido como Planeta Plant.', 'https://dragonball-api.com/planetas/Planeta_Vegeta_en_Dragon_Ball_Super_Broly.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(4, 4, 'Freezer No. 79', 1, 'Planeta artificial utilizado por Freezer como base de operaciones y centro de clonación.', 'https://dragonball-api.com/planetas/PlanetaFreezer.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(5, 5, 'Kanassa', 1, 'Planeta habitado por los Kanassans y conocido por la lucha entre Bardock y los habitantes del planeta.', 'https://dragonball-api.com/planetas/800px-PlanetKannasa.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(6, 6, 'Monmar', 0, 'Planeta donde Gohan y Krillin encontraron las Dragon Balls para revivir a sus amigos durante la Saga de Namek.', 'https://dragonball-api.com/planetas/monmar.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(7, 7, 'Yardrat', 0, 'Planeta de la técnica Instant Transmission, aprendida por Goku durante su estancia.', 'https://dragonball-api.com/planetas/PlanetYardrat.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(8, 11, 'Kaiō del Norte', 0, 'El Planeta Kaio se encuentra al final del largo Camino de la Serpiente. Es donde viven el Kaio del Norte, su mascota Bubbles, al que utiliza como parte de su entrenamiento, y Gregory.', 'https://dragonball-api.com/planetas/Planeta_del_Kaio_del_Norte.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(9, 13, 'Makyo', 0, 'Makyo es un planeta y la fuente de alimentación de todos los malévolos, especialmente Garlic Jr., que solo aparece durante el Arco de Garlic Jr. de Dragon Ball Z.', 'https://dragonball-api.com/planetas/Makyo_Star.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(10, 14, 'Babari', 0, 'Planeta habitado por los Babari, es un planeta telúrico del Universo 10 donde residen los babarianos, hizo su primera aparición en el episodio 54 de Dragon Ball Super. Es donde Tarble, el hermano de Vegeta, se refugió.', 'https://dragonball-api.com/planetas/Planeta_Babari.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(11, 15, 'Tsufur (Universo 6)', 0, 'Planeta natal de los Tsufur, la raza a la que pertenecía el Dr. Raichi.', 'https://dragonball-api.com/planetas/tsufur.webp', ),
(12, 16, 'Desconocido', 0, 'Sin informacion', 'https://dragonball-api.com/planetas/planetwhatis.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(13, 18, 'Otro Mundo', 0, 'El Otro Mundo en contraparte al Mundo de los vivos, es, en Dragon Ball, la versión del mundo de los muertos. Es donde los personajes van cuando mueren, y también donde residen las deidades superiores del universo. En el episodio 53 del anime, el Otro Mundo fue descrito como \"la dimensión siguiente\", y el acto de desear traer a la vida a una persona muerta con las Esferas del Dragón se llama \"traer (a ellos) a esta dimensión.', 'https://dragonball-api.com/planetas/otro mundo.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(14, 19, 'Planeta de Bills ', 0, 'Planeta de Bills un cuerpo celeste ubicado dentro del mundo de los vivos del Universo 7, el cual aparece por primera vez en la película Dragon Ball Z: La Batalla de los Dioses.', 'https://dragonball-api.com/planetas/Templo_de_Bills2.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(15, 20, 'Planeta del Gran Kaio', 0, 'El Planeta del Gran Kaio es donde se organiza el Torneo de Artes Marciales del Otro Mundo en honor a la muerte del Kaio del Norte (Kaito), donde participan guerreros poderosos.', 'https://dragonball-api.com/planetas/Planetadaikaiosama.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(16, 21, 'Nucleo del Mundo', 0, 'El Núcleo del Mundo es el planeta nativo de toda la especie nucleica, del cual surgen los benévolos Kaio y Kaio-shin, así como los malévolos Makaio, Makaio-shin y Dioses Demoníacos en contrapartida.', 'https://dragonball-api.com/planetas/nucleo_mundo.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(17, 22, 'Planeta sagrado', 0, 'El Planeta Sagrado es el planeta localizado en el Reino Kaio-shin donde residen los Kaio-shin del Universo 7. No debe ser confundido con el Núcleo del Mundo.El Reino de los Kaio-shin, en el cual se encuentra localizado el planeta, es un reino especial completamente separado en el macrocosmos del Universo 7, es decir, está separado del Otro Mundo, del Mundo de los vivos y del Reino Demoníaco Oscuro.', 'https://dragonball-api.com/planetas/Planeta_Sagrado.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(18, 23, 'Nuevo Planeta Tsufrui', 0, 'El Nuevo Planeta Plant, también conocido como el Nuevo Planeta Tsufru, es el nombre que se le da al nuevo hogar de los Tsufruianos controlados por Vegeta Baby, ocasionado gracias al deseo concedido por medio de las Esferas del Dragón Definitivas de restaurar el Planeta Plant en la órbita de la Tierra.', 'https://dragonball-api.com/planetas/Nuevo_planeta_plant.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(19, 24, 'Templo móvil del Rey de Todo', 0, 'El templo móvil del Rey de Todo (sala del trono), es como su nombre lo indica, un templo móvil en el cual reside los tronos de los dos Reyes de Todo en el Lugar de Supervivencia en Dragon Ball Super.', 'https://dragonball-api.com/planetas/Trono_del_Rey_de_Todo.webp', );
INSERT INTO `planetas` (`id`, `id_api`, `name`, `is_destroyed`, `description`, `image_url`, `image_blob`) VALUES
(20, 25, 'Universo 11', 0, 'El Universo 11, es, como su nombre lo indica, el undécimo de los doce universos existentes actualmente en el mundo de Dragon Ball. Este es gemelo del Universo 2 y el lugar de origen de las Tropas del Orgullo.', 'https://dragonball-api.com/planetas/Universo_11.webp', );
